package com.dronefleet.event;import java.util.concurrent.CopyOnWriteArrayList;import java.util.function.Consumer;public final class EventBus{private final CopyOnWriteArrayList<Consumer<DeliveryEvent>> listeners=new CopyOnWriteArrayList<>();public void subscribe(Consumer<DeliveryEvent> l){listeners.add(l);}public void publish(DeliveryEvent e){listeners.forEach(l->{try{l.accept(e);}catch(Exception ignored){}});}}
